75	    /**
76	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
77	     * domain containing at least one dot, with no whitespace in any part.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
83	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
84	     * addresses are not durable contact details. Entries are stored lower-cased.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
87	        "mailinator.com",
88	        "tempmail.com",
89	        "guerrillamail.com");
