91	    /**
92	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
93	     * new owner's id, customer code, registration date, membership level and membership number.
94	     */
95	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
96	
97	    /**
98	     * Common street-type abbreviations expanded during address normalization. Keys are the
99	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
100	     * expanded form it is replaced with.
101	     */
102	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
103	        "ST", "STREET",
104	        "RD", "ROAD",
105	        "AVE", "AVENUE");
106	
107	    /**
108	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
109	     * is at capacity and cannot take any more.
110	     */
111	    private static final int CITY_CAPACITY = 50;
112	
113	    /**
114	     * The maximum number of owners that may be registered in a single day. Once this many owners
115	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
116	     * owners can be created that day.
117	     */
118	    private static final int DAILY_OWNER_LIMIT = 100;
119	
120	    /**
121	     * The number of owners that may be registered on a single business day before a response starts
122	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
123	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
124	     * high volume.
125	     */
126	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
127	
128	    /**
129	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
130	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
131	     * date is rolled forward off a Saturday or Sunday.
132	     */
133	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
134	        LocalDate.parse("2026-01-01"),
135	        LocalDate.parse("2026-01-26"),
136	        LocalDate.parse("2026-04-25"),
137	        LocalDate.parse("2026-12-25"),
138	        LocalDate.parse("2026-12-28"));
139	
140	    /**
141	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
142	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
143	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
144	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
145	     */
146	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
147	        "61", 9,
148	        "1", 10);
149	
150	    /**
151	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
152	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
153	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
154	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
155	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
156	     */
157	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
158	        "NSW", new int[] {2000, 2099},
159	        "VIC", new int[] {3000, 3099},
160	        "QLD", new int[] {4000, 4099});
161	
162	    /**
163	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
164	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
165	     * any 4-digit postcode.
166	     */
167	    private static final Map<String, String> CITY_REGION = Map.of(
168	        "Sydney", "NSW",
169	        "Melbourne", "VIC",
170	        "Brisbane", "QLD");
