226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
229	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
230	        if (replay != null) {
231	            return replay;
232	        }
233	        validateRequiredFields(ownerFieldsDto);
234	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
235	        LocalDate registrationDate = toBusinessDay(
236	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
237	        rejectDailyLimitReached(registrationDate);
238	        HttpHeaders headers = new HttpHeaders();
239	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
240	        applyAddress(owner, ownerFieldsDto);
241	        rejectCityAtCapacity(owner.getCity());
242	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
243	        owner.setTelephone(telephone);
244	        String email = normalizeEmail(ownerFieldsDto.getEmail());
245	        owner.setEmail(email);
246	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
247	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
248	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
249	        rejectDuplicateIdentity(owner);
250	        applyPossibleDuplicate(owner, sharesHousehold);
251	        owner.setRegistrationDate(registrationDate);
252	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
253	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
254	        owner.setMembershipLevel(cappedMembershipLevel(owner));
255	        this.clinicService.saveOwner(owner);
256	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
257	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
258	            owner.getMembershipLevel(), owner.getMembershipNumber());
259	        rememberIdempotentCreate(idempotencyKey, owner.getId());
260	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
261	        applyBulkSignupWarning(ownerDto);
262	        headers.setLocation(UriComponentsBuilder.newInstance()
263	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
264	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
265	    }
266	
267	    /**
268	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
269	     * successful create. When the key has a remembered owner that still exists, the originally created
270	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
271	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
272	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
273	     *
274	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
275	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
276	     */
277	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
278	        if (isBlank(idempotencyKey)) {
279	            return null;
280	        }
281	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
282	        if (ownerId == null) {
283	            return null;
284	        }
285	        Owner owner = this.clinicService.findOwnerById(ownerId);
286	        if (owner == null) {
287	            return null;
288	        }
289	        HttpHeaders headers = new HttpHeaders();
290	        headers.setLocation(UriComponentsBuilder.newInstance()
291	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
292	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
293	        applyBulkSignupWarning(ownerDto);
294	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
295	    }
296	
297	    /**
298	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
299	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
300	     * blank key is ignored, leaving that create non-idempotent.
301	     *
302	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
303	     * @param ownerId        the id of the owner that was just created
304	     */
305	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
306	        if (!isBlank(idempotencyKey)) {
307	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
308	        }
309	    }
