406	    /**
407	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
408	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
409	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
410	     *
411	     * @param ownerFieldsDto the submitted owner fields
412	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
413	     *                                     name of every offending field
414	     */
415	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
416	        List<String> missingFields = new ArrayList<>();
417	        if (isBlank(ownerFieldsDto.getFirstName())) {
418	            missingFields.add("firstName");
419	        }
420	        if (isBlank(ownerFieldsDto.getLastName())) {
421	            missingFields.add("lastName");
422	        }
423	        if (!hasAddress(ownerFieldsDto)) {
424	            missingFields.add("address");
425	        }
426	        if (isBlank(ownerFieldsDto.getCity())) {
427	            missingFields.add("city");
428	        }
429	        if (isBlank(ownerFieldsDto.getTelephone())) {
430	            missingFields.add("telephone");
431	        }
432	        if (!missingFields.isEmpty()) {
433	            throw new InvalidOwnerFieldsException(missingFields);
434	        }
435	    }
436	
437	    private boolean isBlank(String value) {
438	        return value == null || value.isBlank();
439	    }
