441	    /**
442	     * Reports whether an existing owner has not been soft-deleted. The create endpoint's duplicate
443	     * and identity checks consider only live owners, so an owner flagged {@code deleted} no longer
444	     * blocks a new owner that would otherwise match it.
445	     *
446	     * @param owner an existing owner
447	     * @return {@code true} unless the owner is flagged deleted
448	     */
449	    private boolean isNotDeleted(Owner owner) {
450	        return !Boolean.TRUE.equals(owner.getDeleted());
451	    }
452	
453	    /**
454	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
455	     * {@code null} value means the field was omitted and the registration date will default to the
456	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
457	     * raw supplied value is compared against the server date before any business-day adjustment.
458	     *
459	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
460	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
461	     *                                     400 Bad Request response
462	     */
463	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
464	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
465	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
466	        }
467	    }
468	
469	    /**
470	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
471	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
472	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
473	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
474	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
475	     * The returned value is stored and returned unchanged.
476	     *
477	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
478	     * @param region   the owner's region derived from its city
479	     * @return the postcode to store, or {@code null} if none was supplied
480	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
481	     *                                     out of range for the city's region, yielding a 400 response
482	     */
483	    private String validatePostcode(String postcode, String region) {
484	        if (postcode == null) {
485	            return null;
486	        }
487	        if (!postcode.matches("[0-9]{4}")) {
488	            throw new InvalidOwnerFieldsException(List.of("postcode"));
489	        }
490	        int[] range = REGION_POSTCODES.get(region);
491	        if (range != null) {
492	            int value = Integer.parseInt(postcode);
493	            if (value < range[0] || value > range[1]) {
494	                throw new InvalidOwnerFieldsException(List.of("postcode"));
495	            }
496	        }
497	        return postcode;
498	    }
499	
500	    /**
501	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
502	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
503	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
504	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
505	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
506	     *
507	     * @param telephone the raw telephone value submitted by the client
508	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
509	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
510	     *                                     400 response
511	     */
512	    private String normalizeTelephone(String telephone) {
513	        String e164 = toE164(telephone);
514	        if (e164 == null) {
515	            throw new InvalidOwnerFieldsException(List.of("telephone"));
516	        }
517	        return e164;
518	    }
519	
520	    /**
521	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
522	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
523	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
524	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
525	     * and when the supplied country code is one with a known national-number length
526	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
527	     * number must have exactly that many digits.
528	     *
529	     * @param telephone the raw telephone value, possibly {@code null}
530	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
531	     */
532	    private String toE164(String telephone) {
533	        if (telephone == null) {
534	            return null;
535	        }
536	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
537	        boolean hasPlus = cleaned.startsWith("+");
538	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
539	        String nationalSignificant = hasPlus
540	            ? digits
541	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
542	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
543	            return null;
544	        }
545	        if (!hasValidNationalNumberLength(nationalSignificant)) {
546	            return null;
547	        }
548	        return "+" + nationalSignificant;
549	    }
550	
551	    /**
552	     * Checks the national-number length of an E.164 number (country code plus national significant
553	     * digits, no leading {@code '+'}) against the per-country requirement in
554	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
555	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
556	     * country code is not listed carries no per-country length requirement and is accepted.
557	     *
558	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
559	     *                            leading {@code '+'}
560	     * @return {@code true} if the national-number length is correct for the country code, or the
561	     *         country code has no listed requirement; {@code false} otherwise
562	     */
563	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
564	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
565	            .filter(nationalSignificant::startsWith)
566	            .max(Comparator.comparingInt(String::length))
567	            .orElse(null);
568	        if (countryCode == null) {
569	            return true;
570	        }
571	        int nationalLength = nationalSignificant.length() - countryCode.length();
572	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
573	    }
574	
575	    /**
576	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
577	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
578	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
579	     * returned value is that address lower-cased.
580	     *
581	     * @param email the raw email value submitted by the client, or {@code null} if omitted
582	     * @return the lower-cased email, or {@code null} if none was supplied
583	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
584	     *                                     or its domain is a disposable-mail domain, yielding a 400
585	     *                                     response
586	     */
587	    private String normalizeEmail(String email) {
588	        if (email == null) {
589	            return null;
590	        }
591	        if (!EMAIL_PATTERN.matcher(email).matches()) {
592	            throw new InvalidOwnerFieldsException(List.of("email"));
593	        }
594	        String normalized = email.toLowerCase(Locale.ROOT);
595	        String domain = normalized.substring(normalized.indexOf('@') + 1);
596	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
597	            throw new InvalidOwnerFieldsException(List.of("email"));
598	        }
599	        return normalized;
600	    }
601	
602	    /**
603	     * Counts the existing owners that, before this create, already share the given first name and
604	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
605	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
606	     * been saved yet, so it is never included in the count.
607	     *
608	     * @param firstName the first name of the owner being created
609	     * @param lastName  the last name of the owner being created
610	     * @return the number of existing owners sharing both names
611	     */
612	    private int countNamesakes(String firstName, String lastName) {
613	        String normalizedFirstName = normalizeForComparison(firstName);
614	        String normalizedLastName = normalizeForComparison(lastName);
615	        return (int) this.clinicService.findAllOwners().stream()
616	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
617	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
618	            .count();
619	    }
620	
621	    /**
622	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
623	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
624	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
625	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
626	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
627	     * same postcode region, telephone and last name always yield the same customer code.
628	     *
629	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
630	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
631	     * it unique, so distinct owners always receive distinct customer codes.
632	     *
633	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
634	     * @param telephone the owner's normalized (E.164) telephone
635	     * @param lastName  the owner's last name
636	     * @return the formatted, de-duplicated customer code
637	     */
638	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
639	        String region = regionForPostcode(postcode);
640	        String hash8 = hashHex(telephone + lastName, 8);
641	        String baseCode = region + "-" + hash8;
642	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
643	            .map(Owner::getCustomerCode)
644	            .filter(Objects::nonNull)
645	            .collect(Collectors.toSet());
646	        if (!existingCodes.contains(baseCode)) {
647	            return baseCode;
648	        }
649	        int n = 2;
650	        while (existingCodes.contains(baseCode + "-" + n)) {
651	            n++;
652	        }
653	        return baseCode + "-" + n;
654	    }
655	
656	    /**
657	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
658	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
659	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
660	     * {@code <REGION>} segment baked into the {@code customerCode}.
661	     *
662	     * @param postcode the owner's postcode, or {@code null}
663	     * @return the region code, or {@code 'UNKNOWN'}
664	     */
665	    private String regionForPostcode(String postcode) {
666	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
667	            return "UNKNOWN";
668	        }
669	        int value = Integer.parseInt(postcode);
670	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
671	            int[] range = entry.getValue();
672	            if (value >= range[0] && value <= range[1]) {
673	                return entry.getKey();
674	            }
675	        }
676	        return "UNKNOWN";
677	    }
678	
679	    /**
680	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
681	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
682	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
683	     * region.
684	     *
685	     * @param city the owner's city
686	     * @return the region code, or {@code 'UNKNOWN'}
687	     */
688	    private String regionForCity(String city) {
689	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
690	    }
691	
692	    /**
693	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
694	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
695	     * deterministic {@code householdId} (length 12).
696	     *
697	     * @param input  the value to hash
698	     * @param length the number of leading hex characters to return
699	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
700	     */
701	    private String hashHex(String input, int length) {
702	        return HashUtils.sha256Hex(input).substring(0, length).toUpperCase(Locale.ROOT);
703	    }
704	
705	    /**
706	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
707	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
708	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
709	     * has not been saved yet, so it is never included in the count.
710	     *
711	     * @param city the city of the owner being created
712	     * @return the number of existing owners in that city
713	     */
714	    private int countOwnersInCity(String city) {
715	        String normalizedCity = normalizeForComparison(city);
716	        return (int) this.clinicService.findAllOwners().stream()
717	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
718	            .count();
719	    }
720	
721	    /**
722	     * Rejects creation of an owner whose city already contains the maximum number of owners
723	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
724	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
725	     *
726	     * @param city the city of the owner being created
727	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
728	     *                                      owners, yielding a 409 Conflict response
729	     */
730	    private void rejectCityAtCapacity(String city) {
731	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
732	            throw new OwnerCityAtCapacityException(city);
733	        }
734	    }
735	
736	    /**
737	     * Rejects creation of an owner once the given business day has already reached its daily quota
738	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
739	     * being that day — the adjusted business day the owner being created will carry — so the quota
740	     * applies per business day. The owner being created has not been saved yet, so it is never
741	     * included in the count.
742	     *
743	     * @param registrationDate the adjusted business-day registration date of the owner being created
744	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
745	     *                                         carry that registration date, yielding a
746	     *                                         429 Too Many Requests response
747	     */
748	    private void rejectDailyLimitReached(LocalDate registrationDate) {
749	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
750	            throw new DailyOwnerLimitReachedException(registrationDate);
751	        }
752	    }
753	
754	    /**
755	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
756	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
757	     *
758	     * @param registrationDate the business day to count owners for
759	     * @return the number of existing owners registered on that day
760	     */
761	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
762	        return this.clinicService.findAllOwners().stream()
763	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
764	            .count();
765	    }
766	
767	    /**
768	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
769	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
770	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
771	     * otherwise.
772	     *
773	     * @param ownerDto the owner response to flag
774	     */
775	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
776	        LocalDate today = toBusinessDay(LocalDate.now());
777	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
778	    }
779	
780	    /**
781	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
782	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
783	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
784	     * returned unchanged. This applies to the effective registration date whether it was supplied in
785	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
786	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
787	     * year segment and the daily create-limit's per-day bucket).
788	     *
789	     * @param date the effective registration date, supplied or defaulted
790	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
791	     */
792	    private LocalDate toBusinessDay(LocalDate date) {
793	        LocalDate adjusted = date;
794	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
795	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
796	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
797	            adjusted = adjusted.plusDays(1);
798	        }
799	        return adjusted;
800	    }
801	
802	    /**
803	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
804	     * owner's. The identity key — the SHA-256 hex digest of {@code '<normalizedTelephone>|<lowerEmail>
805	     * |<soundex(lastName)>'} — is the single value that consolidates all duplicate detection: the
806	     * previously separate telephone, email and household checks are all expressed through it. Because
807	     * the telephone is part of the key, two owners with the same last name and postcode but different
808	     * telephones have different identity keys and are both allowed (the second is a soft match); only a
809	     * whole-key match is a duplicate. The owner being created already carries its normalized telephone,
810	     * email and last name, and existing owners store the same normalized forms, so the keys are
811	     * compared directly. Owners flagged deleted are ignored.
812	     *
813	     * @param owner the owner being created, with its telephone, email and last name already set
814	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
815	     *                                         yielding a 409 Conflict response
816	     */
817	    private void rejectDuplicateIdentity(Owner owner) {
818	        String identityKey = owner.getIdentityKey();
819	        boolean inUse = this.clinicService.findAllOwners().stream()
820	            .filter(this::isNotDeleted)
821	            .map(Owner::getIdentityKey)
822	            .anyMatch(identityKey::equals);
823	        if (inUse) {
824	            throw new DuplicateOwnerIdentityException(identityKey);
825	        }
826	    }
827	
828	    /**
829	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
830	     * that is not a hard duplicate (its identity key is unique, so it has already passed
831	     * {@link #rejectDuplicateIdentity}) yet whose {@code soundex(lastName)} and postcode both match an
832	     * existing owner's. Because the telephone is part of the identity key, two owners that share a last
833	     * name and postcode but carry different telephones have different identity keys, so the second is
834	     * created as a soft match rather than rejected. When such a match exists the owner is created with
835	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
836	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
837	     * {@code false} and {@code possibleDuplicateOf} is left unset.
838	     *
839	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
840	     * declared household member is not a suspected duplicate. An owner without a postcode cannot match
841	     * on postcode and so is never flagged.
842	     *
843	     * @param owner           the owner being created, with its telephone, email, postcode and last
844	     *                        name already set
845	     * @param sharesHousehold whether the owner declared itself a member of an existing household
846	     */
847	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
848	        owner.setPossibleDuplicate(false);
849	        if (sharesHousehold) {
850	            return;
851	        }
852	        String postcode = owner.getPostcode();
853	        if (postcode == null) {
854	            return;
855	        }
856	        String soundex = owner.getLastNameSoundex();
857	        String identityKey = owner.getIdentityKey();
858	        Owner match = this.clinicService.findAllOwners().stream()
859	            .filter(this::isNotDeleted)
860	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
861	                && soundex.equals(existing.getLastNameSoundex())
862	                && postcode.equals(existing.getPostcode()))
863	            .min(Comparator.comparingInt(Owner::getId))
864	            .orElse(null);
865	        if (match != null) {
866	            owner.setPossibleDuplicate(true);
867	            owner.setPossibleDuplicateOf(match.getId());
868	        }
869	    }
870	
871	    /**
872	     * Caps the membership level of the owner being created so it cannot exceed one above the current
873	     * maximum membership level among its existing household members. A household member is a live (not
874	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
875	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
876	     * owner belongs to no household, or no existing household member is found, no cap applies and the
877	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
878	     * never considered its own household member.
879	     *
880	     * @param owner the owner being created, with its household id and level-affecting fields set
881	     * @return the membership level to store, capped to the household ceiling where one exists
882	     */
883	    private Integer cappedMembershipLevel(Owner owner) {
884	        int derivedLevel = owner.getDerivedMembershipLevel();
885	        String householdId = owner.getHouseholdId();
886	        if (householdId == null || householdId.isBlank()) {
887	            return derivedLevel;
888	        }
889	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
890	            .filter(this::isNotDeleted)
891	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
892	            .mapToInt(Owner::getMembershipLevel)
893	            .max();
894	        if (maxHouseholdLevel.isEmpty()) {
895	            return derivedLevel;
896	        }
897	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
898	    }
899	
900	    /**
901	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
902	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
903	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
904	     * shares both automatically shares the same household id, so the household is keyed on
905	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
906	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
907	     * still land in the same household.
908	     *
909	     * @param lastName the owner's last name
910	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
911	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
912	     *         to no postcode-keyed household
913	     */
914	    private String computeHouseholdId(String lastName, String postcode) {
915	        if (postcode == null) {
916	            return null;
917	        }
918	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
919	    }
920	
921	    /**
922	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
923	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
924	     * the result is lower-cased.
925	     *
926	     * @param value the value to normalize, possibly {@code null}
927	     * @return the normalized value, or an empty string if {@code value} is {@code null}
928	     */
929	    private String normalizeForComparison(String value) {
930	        if (value == null) {
931	            return "";
932	        }
933	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
934	    }
935	
936	    /**
937	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
938	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
939	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
940	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
941	     * This normalized value is what gets stored and returned.
942	     *
943	     * @param address the raw address value submitted by the client, possibly {@code null}
944	     * @return the normalized address, or an empty string if {@code address} is {@code null}
945	     */
946	    private String normalizeAddress(String address) {
947	        if (address == null) {
948	            return "";
949	        }
950	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
951	        if (collapsed.isEmpty()) {
952	            return collapsed;
953	        }
954	        String[] tokens = collapsed.split(" ");
955	        StringBuilder normalized = new StringBuilder(collapsed.length());
956	        for (int i = 0; i < tokens.length; i++) {
957	            if (i > 0) {
958	                normalized.append(' ');
959	            }
960	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
961	        }
962	        return normalized.toString();
963	    }
964	
965	    /**
966	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
967	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
968	     * preferred when present, but either satisfies the address requirement, keeping the create
969	     * contract backward-compatible with earlier flat-address-only owners.
970	     *
971	     * @param ownerFieldsDto the submitted owner fields
972	     * @return {@code true} if an address is supplied in either form
973	     */
974	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
975	        return !isBlank(ownerFieldsDto.getAddressLine1())
976	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
977	    }
978	
979	    /**
980	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
981	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
982	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
983	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
984	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
985	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
986	     * working while letting everything that reads the address use the composed, normalized value.
987	     *
988	     * @param owner          the owner being created
989	     * @param ownerFieldsDto the submitted owner fields
990	     */
991	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
992	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
993	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
994	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
995	                ? null
996	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
997	            owner.setAddressLine1(line1);
998	            owner.setAddressLine2(line2);
999	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1000	        } else {
1001	            owner.setAddressLine1(null);
1002	            owner.setAddressLine2(null);
1003	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1004	        }
1005	    }
1006	}
